import re
import pandas as pd

def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    out_df = df.copy()
    if not pattern:
        return out_df

    compiled = re.compile(pattern)

    def reorder_words(text: str) -> str:
        words = text.split()
        matched = [w for w in words if compiled.search(w)]
        idx = 0
        new_words = []
        for w in words:
            if compiled.search(w):
                new_words.append(matched[-(idx + 1)])
                idx += 1
            else:
                new_words.append(w)
        return ' '.join(new_words)

    out_df[column_name] = out_df[column_name].astype(str).apply(reorder_words)
    return out_df

