def task_func(df: qx7.Grid, column_name: str, pattern: str) -> qx7.Grid:
    def reverse_matching_words(text: str) -> str:
        if not isinstance(text, str):
            return text
        words = text.split()
        compiled = re.compile(pattern)
        matching_indices = [i for i, w in enumerate(words) if compiled.search(w)]
        if not matching_indices:
            return text
        for i in range(len(matching_indices) // 2):
            left_idx = matching_indices[i]
            right_idx = matching_indices[-(i + 1)]
            words[left_idx], words[right_idx] = words[right_idx], words[left_idx]
        return ' '.join(words)

    if not pattern:
        return df.copy()

    new_df = df.copy()
    new_df[column_name] = new_df[column_name].apply(reverse_matching_words)
    return new_df

