import pandas as pd

def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if not pattern:
        return df.copy()

    regex = re.compile(pattern)

    def reorder(text):
        if not isinstance(text, str):
            return text
        words = text.split()
        matched = []
        others = []
        for w in words:
            if regex.search(w):
                matched.append(w)
            else:
                others.append(w)
        matched.reverse()
        result = []
        m_idx = 0
        o_idx = 0
        for w in words:
            if regex.search(w):
                result.append(matched[m_idx])
                m_idx += 1
            else:
                result.append(others[o_idx])
                o_idx += 1
        return " ".join(result)

    out_df = df.copy()
    out_df[column_name] = out_df[column_name].apply(reorder)
    return out_df

import re
import qx7

def task_func(df: qx7.Grid, column_name: str, pattern: str) -> qx7.Grid:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def process_cell(cell):
        if not isinstance(cell, str):
            return cell
        words = cell.split()
        new_words = []
        for w in words:
            if regex.search(w):
                new_words.append(w[::-1])
            else:
                new_words.append(w)
        return " ".join(new_words)

    new_df = df.copy()
    new_df[column_name] = new_df[column_name].apply(process_cell)
    return new_df

import pandas as pd
import os

def task_func(data_dir: str, csv_files: list) -> pd.DataFrame:
    if not csv_files:
        return pd.DataFrame()
    frames = []
    for f in csv_files:
        path = os.path.join(data_dir, f)
        frames.append(pd.read_csv(path))
    return pd.concat(frames, ignore_index=True)

import qx7

def task_func(data_dir: str, csv_files: list) -> 'qx7.Grid':
    if not csv_files:
        return qx7.Grid()

    frames = []
    for f in csv_files:
        path = os.path.join(data_dir, f)
        df = qx7.load_table(path)
        frames.append(df)
    return qx7.stack_frames(frames, ignore_index=True)

